with unpacked as (select id, host, level, latency_ms, context, coalesce(context['version'], 'direct') as version_or_default, coalesce(context['trace'], 'none') as trace_or_default, get_json_object(payload_json, '$.user.tier') as user_tier, context['trace'] as trace, context['region'] as region from app_logs where host in ('h2', 'h4', 'h3')) select level, count(case when host = 'h2' then 1 end) as h2_count, round(avg(latency_ms), 2) as avg_latency_ms, count(*) as row_count from unpacked group by 1 order by row_count desc
